from __future__ import annotations

import base64
import gzip
import subprocess

PATCH_B64 = r"""[... ELLIPSIZATION ...]"""

patch = gzip.decompress(base64.b64decode(PATCH_B64))
subprocess.run(["git", "apply", "--whitespace=error-all", "-"], input=patch, check=True)
print("Validated global audit cleanup applied to canonical repository files.")
